import sys
from collections import deque

class BTreeNode:
    def __init__(self, leaf=False):
        self.keys = []
        self.children = []
        self.leaf = leaf

class BTree:
    def __init__(self, order):
        self.root = None
        self.order = order
        self.min_keys = (order + 1) // 2 - 1
        self.max_keys = order - 2

    def insert(self, key):
        if self.root is None:
            self.root = BTreeNode(leaf=True)
            self.root.keys.append(key)
        else:
            if len(self.root.keys) == self.max_keys + 1:
                new_root = BTreeNode(leaf=False)
                new_root.children.append(self.root)
                self.root = new_root
                self._split_child(self.root, 0)
            self._insert_non_full(self.root, key)

    def _split_child(self, parent, index):
        order = self.order
        full_child = parent.children[index]

        mid = order // 2

        new_node = BTreeNode(leaf=full_child.leaf)

        for i in range(mid + 1, len(full_child.keys)):
            new_node.keys.append(full_child.keys[i])
        for i in range(mid + 1, len(full_child.children)):
            new_node.children.append(full_child.children[i])

        while len(full_child.keys) > mid:
            full_child.keys.pop()
        while len(full_child.children) > mid + 1:
            full_child.children.pop()

        median_key = full_child.keys.pop()

        parent.keys.insert(index, median_key)
        parent.children.insert(index + 1, new_node)

    def _insert_non_full(self, node, key):
        if node.leaf:
            i = len(node.keys) - 1
            while i >= 0 and key < node.keys[i]:
                i -= 1
            node.keys.insert(i + 1, key)
        else:
            i = len(node.keys) - 1
            while i >= 0 and key < node.keys[i]:
                i -= 1
            i += 1

            if len(node.children[i].keys) == self.max_keys + 1:
                self._split_child(node, i)
                if key > node.keys[i]:
                    i += 1

            self._insert_non_full(node.children[i], key)

    def level_order(self):
        if self.root is None:
            return []

        result = []
        queue = deque([self.root])

        while queue:
            level_size = len(queue)
            level_keys = []

            for _ in range(level_size):
                node = queue.popleft()
                level_keys.extend(node.keys)
                for child in node.children:
                    queue.append(child)

            result.append(level_keys)

        return result

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    keys = list(map(int, data[2:2+n]))

    tree = BTree(m)
    for key in keys:
        tree.insert(key)

    levels = tree.level_order()
    for level in levels:
        print(' '.join(map(str, level)))

if __name__ == "__main__":
    main()
